import json
from itertools import permutations

# Nationality codes: K=South Korea, F=France, B=Britain, G=Germany
NAMES = {'K': 'South Korea', 'F': 'France', 'B': 'Britain', 'G': 'Germany'}

# Languages each person can speak (own language plus any stated ones)
LANG = {
    'K': {'K'},                 # Korean: no foreign languages
    'F': {'F', 'G'},            # French: can speak German
    'B': {'B', 'K'},            # British: can speak Korean
    'G': {'K', 'F', 'B', 'G'},  # German: speaks all four
}

OPTIONS = {
    'A': ['B', 'G', 'K', 'F'],
    'B': ['F', 'B', 'G', 'K'],
    'C': ['G', 'B', 'F', 'K'],
    'D': ['G', 'B', 'K', 'F'],
}

def comm(a, b):
    # Two people can communicate if they share a language
    return bool(LANG[a] & LANG[b])

def comm_neighbors(perm, n):
    i = perm.index(n)
    return sum(1 for j in (i - 1, i + 1)
               if 0 <= j < len(perm) and comm(n, perm[j]))

valid = []
for perm in permutations(['K', 'F', 'B', 'G']):   # perm[0] is room 1, etc.
    room = {n: i + 1 for i, n in enumerate(perm)}
    ok = (
        room['K'] > room['G']                # Korean's room larger than German's
        and comm_neighbors(perm, 'K') == 0   # Korean communicates with no neighbor
        and comm_neighbors(perm, 'F') == 0   # French communicates with no neighbor
        and comm_neighbors(perm, 'B') == 1   # British communicates with exactly one neighbor
    )
    if ok:
        valid.append(tuple(perm))

matches = [opt for opt, seq in OPTIONS.items() if tuple(seq) in valid]
final_answer = matches[0] if len(matches) == 1 else 'UNSUPPORTED'

evidence = {
    "valid_room_orders": [[NAMES[n] for n in p] for p in valid],
    "matching_options": matches,
    "enumerated_permutations": 24,
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}))
